"""API key lifecycle service.

Mints, lists and revokes API keys. Only the SHA-256 hash of each key is
stored server-side; the plaintext is shown exactly once at mint time.
"""

import hashlib
import os
import secrets
import sqlite3
import string
from datetime import datetime, timezone

from fastapi import Depends, FastAPI, HTTPException, Request
from fastapi.responses import JSONResponse

DB_PATH = os.environ.get("DB_PATH", "keys.db")

BASE62 = string.ascii_letters + string.digits
KEY_PREFIX = "sk_live_"
RANDOM_LEN = 24

app = FastAPI(title="API Key Lifecycle Service")


# ---------------------------------------------------------------- database


def get_conn() -> sqlite3.Connection:
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode=WAL")
    return conn


def init_db() -> None:
    with get_conn() as conn:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS api_keys (
                id            INTEGER PRIMARY KEY AUTOINCREMENT,
                key_hash      TEXT NOT NULL UNIQUE,
                prefix        TEXT NOT NULL,
                created_at    TEXT NOT NULL,
                last_used_at  TEXT,
                revoked       INTEGER NOT NULL DEFAULT 0
            )
            """
        )


@app.on_event("startup")
def _startup() -> None:
    init_db()


def utcnow_iso() -> str:
    return datetime.now(timezone.utc).isoformat()


# ---------------------------------------------------------------- security


def hash_key(plaintext: str) -> str:
    return hashlib.sha256(plaintext.encode("utf-8")).hexdigest()


def require_valid_key(request: Request) -> sqlite3.Row:
    """Dependency: authenticate via Authorization: Bearer sk_live_..."""
    auth = request.headers.get("Authorization", "")
    if not auth.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Missing bearer token")
    plaintext = auth[len("Bearer "):]
    row = get_conn().execute(
        "SELECT * FROM api_keys WHERE key_hash = ?", (hash_key(plaintext),)
    ).fetchone()
    if row is None or row["revoked"]:
        raise HTTPException(status_code=401, detail="Invalid or revoked API key")
    with get_conn() as conn:
        conn.execute(
            "UPDATE api_keys SET last_used_at = ? WHERE id = ?",
            (utcnow_iso(), row["id"]),
        )
    return row


# ---------------------------------------------------------------- routes


@app.post("/keys", status_code=201)
def mint_key():
    """Mint a new key. The plaintext is returned exactly once."""
    plaintext = KEY_PREFIX + "".join(secrets.choice(BASE62) for _ in range(RANDOM_LEN))
    with get_conn() as conn:
        cursor = conn.execute(
            "INSERT INTO api_keys (key_hash, prefix, created_at) VALUES (?, ?, ?)",
            (hash_key(plaintext), plaintext[:8], utcnow_iso()),
        )
        key_id = cursor.lastrowid
    return JSONResponse(
        status_code=201,
        content={"id": key_id, "key": plaintext, "prefix": plaintext[:8]},
    )


@app.get("/keys")
def list_keys(_row: sqlite3.Row = Depends(require_valid_key)):
    with get_conn() as conn:
        rows = conn.execute(
            "SELECT id, prefix, created_at, last_used_at, revoked "
            "FROM api_keys ORDER BY id"
        ).fetchall()
    return {
        "keys": [
            {
                "id": r["id"],
                "prefix": r["prefix"],
                "created_at": r["created_at"],
                "last_used_at": r["last_used_at"],
                "revoked": bool(r["revoked"]),
            }
            for r in rows
        ]
    }


@app.delete("/keys/{key_id}", status_code=204)
def revoke_key(key_id: int):
    with get_conn() as conn:
        cur = conn.execute("SELECT id FROM api_keys WHERE id = ?", (key_id,))
        if cur.fetchone() is None:
            raise HTTPException(status_code=404, detail="Key not found")
        conn.execute("UPDATE api_keys SET revoked = 1 WHERE id = ?", (key_id,))
    return JSONResponse(status_code=204, content=None)

